CREATE TABLE IF NOT EXISTS "Destination" (id bigint generated always as identity primary key, city text not null, country text not null, image text, description text, rating numeric(3,1) default 4.5, duration text, price text, category text, created_at timestamptz default now()); CREATE TABLE IF NOT EXISTS "Package" (id bigint generated always as identity primary key, tag text, "tagColor" text, title text not null, subtitle text, image text, price integer default 0, "originalPrice" integer default 0, duration text, "groupSize" text, rating numeric(3,1) default 4.5, reviews integer default 0, includes text default '[]', highlight text, category text, created_at timestamptz default now()); CREATE TABLE IF NOT EXISTS "FAQ" (id bigint generated always as identity primary key, q text not null, a text not null, created_at timestamptz default now()); CREATE TABLE IF NOT EXISTS "Testimonial" (id bigint generated always as identity primary key, name text not null, location text, avatar text, rating integer default 5, text text, trip text, created_at timestamptz default now()); CREATE TABLE IF NOT EXISTS "Booking" (id bigint generated always as identity primary key, "packageName" text, country text, name text not null, email text not null, phone text, "travelDate" text, participants integer default 1, notes text, status text default 'pending', "totalAmount" integer default 0, "midtrans_order_id" text, created_at timestamptz default now()); CREATE TABLE IF NOT EXISTS "Wishlist" (id bigint generated always as identity primary key, user_id text not null, destination_id bigint, created_at timestamptz default now()); CREATE TABLE IF NOT EXISTS "Hero" (id bigint generated always as identity primary key, headline text, subheadline text, "badgeText" text, "videoUrl" text, "posterUrl" text, updated_at timestamptz default now()); ALTER TABLE "Destination" DISABLE ROW LEVEL SECURITY; ALTER TABLE "Package" DISABLE ROW LEVEL SECURITY; ALTER TABLE "FAQ" DISABLE ROW LEVEL SECURITY; ALTER TABLE "Testimonial" DISABLE ROW LEVEL SECURITY; ALTER TABLE "Booking" DISABLE ROW LEVEL SECURITY; ALTER TABLE "Wishlist" DISABLE ROW LEVEL SECURITY; ALTER TABLE "Hero" DISABLE ROW LEVEL SECURITY;
